globalvar Number i = 0;
globalvar Number[] arr = [1, 2, 3];
Number pick(Number n): n == 1 ? 10 : 20;
rule: "r" { for (i = 0; i < 3; 1) { i = i + 1; } }
rule: "f" { foreach (Number x in arr) { i = x; } }
rule: "s" { switch (i) { case 1: i = 5; break; case 2: case 3: i = 6; default: i = 7; } }
rule: "fn" { i = pick(1); }
